examples.code:
#include <stdio.h>
typedef struct { int roll; char name[16]; float marks; } Student;
int main(void) {
    Student s = {1, "Asha", 91.5f};
    Student *p = &s;
    printf("%d %s %.1f\n", s.roll, p->name, p->marks);
    return 0;
}

#include <stdio.h>
typedef enum { INT, FLT } Kind;
typedef struct { Kind kind; union { int i; float f; } value; } Tagged;
int main(void) {
    Tagged a = {INT, {.i = 42}};
    Tagged b = {FLT, {.f = 3.5f}};
    printf("%d %.1f %zu\n", a.value.i, b.value.f, sizeof(Tagged));
    return 0;
}

