#include <stdio.h>
typedef struct { char name[16]; int marks; } Student;
int main(void){Student s[3]={{"Asha",90},{"Ravi",75},{"Neha",75}};int sum=0,best=0;for(int i=0;i<3;i++){sum+=s[i].marks;if(s[i].marks>s[best].marks)best=i;}printf("avg=%.1f topper=%s\n",sum/3.0,s[best].name);return 0;}
